import{_ as i,l as m,o as t,c as l,v as e,p as s,x as o,d as n,i as p,S as f}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"Softmax 与数值稳定","description":"","frontmatter":{"title":"Softmax 与数值稳定","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/softmax-numerics.md","filePath":"llm/softmax-numerics.md","lastUpdated":1789023840000}'),d={name:"llm/softmax-numerics.md"};function h(_,a,c,x,u,E){const r=m("Mermaid");return t(),l("div",null,[a[1]||(a[1]=e('<h1 id="softmax-与数值稳定" tabindex="-1">Softmax 与数值稳定 <a class="header-anchor" href="#softmax-与数值稳定" aria-label="Permalink to &quot;Softmax 与数值稳定&quot;">​</a></h1><div class="epigraph"><p>指数把任意实数变成正数，再除以总和就落在单纯形上；若不先平移，指数本身会溢出。</p><footer>—— 据 Bridle, Probabilistic Interpretation of Feedforward Classification Network Outputs, Neurocomputing 1990；Goodfellow et al., Deep Learning, 2016 整理</footer></div><p><a href="/llm/norm-cosine-projection">范数、余弦与投影</a>给出用点积或余弦打分的办法。本课不重推内积。缺口是：一组无约束的分数 \\(z\\in\\mathbb{R}^{K}\\) 还不是概率，而分类、下一词、注意力的权重都需要落在单纯形上的非负向量。方法是 softmax。本课只把它写成「分数 \\(\\to\\) 概率」的数值稳定接口；交叉熵是下一课，缩放点积注意力更在序列单元之后。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>线性层可以输出任意实数。若直接把最大分量当预测，没有可微的「有多确信」，也无法写似然。需要一个光滑映射，把 \\(z\\) 变成 \\(p_i\\gt 0\\)、\\(\\sum_i p_i=1\\)。指数保证正性，归一化保证求和为一。缺口不是再定义一种距离，而是给上一课的分数配上这个映射，并保证在有限精度下算得出来。</p><p>\\(K\\) 可以是类别数，也可以是序列长度。本课不区分这两种用法：形状都是「在最后一轴上做 softmax」。注意力稍后会在这一轴上加权求和；语言模型会在这一轴上取负对数似然。那些目标都假定本课的 \\(p\\) 已经合法且可反传。</p><h3 id="softmax-不是-的「软版本」这么简单" tabindex="-1">Softmax 不是 \\(\\mathrm{argmax}\\) 的「软版本」这么简单 <a class="header-anchor" href="#softmax-不是-的「软版本」这么简单" aria-label="Permalink to &quot;Softmax 不是 $\\mathrm{argmax}$ 的「软版本」这么简单&quot;">​</a></h3><p>\\(\\mathrm{argmax}\\) 不可微，softmax 可微，这只说对了一半。更关键的是：softmax 对分数的平移不变，\\(z\\) 与 \\(z+c\\mathbf{1}\\) 给出同一 \\(p\\)；对缩放不变却不成立，\\(\\beta z\\) 在 \\(\\beta\\to\\infty\\) 时逼近 one-hot。把温度当成「让它更像 argmax」可以，但温度会改变梯度尺度。后课学习率与损失不要把温度藏进未声明的常数里。</p><p><span class="marginnote">实现上从不先算 \\(\\mathrm{e}^{z_i}\\) 再求和。先减 \\(\\max_j z_j\\)，再指数、再归一。这不改数学值，只把指数的自变量拉到非正区间，避免 float32 上 \\(\\mathrm{e}^{90}\\) 溢出成 Inf。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2> \\[p_i=\\frac{\\mathrm{e}^{z_i}}{\\sum_{j=1}^{K}\\mathrm{e}^{z_j}} =\\frac{\\mathrm{e}^{z_i-m}}{\\sum_{j}\\mathrm{e}^{z_j-m}},\\qquad m=\\max_j z_j. \\]<p>最后一轴的形状从 \\((B,K)\\) 或 \\((B,n,K)\\) 变成同形的 \\(p\\)。掩码位置在减最大值之前把对应分数置为很大的负数（或 \\(-\\infty\\) 的有限代替），使 \\(p\\) 在那些位置上接近 \\(0\\)。本课不讨论因果掩码从哪来，只规定：非法位置必须在 softmax 之前处理，不能靠事后把概率乘零——乘零之后不再归一，质量和不为 \\(1\\)。</p><p>Jacobian 有简单形式：\\(\\partial p_i/\\partial z_k=p_i(\\delta_{ik}-p_k)\\)。后课交叉熵会与它对消成 \\(p-y\\)，那是下一课的代数；本课记下「饱和时梯度小」：某一 \\(p_i\\approx 1\\) 时，其余分量几乎拉不动 \\(z\\)。</p>',13)),(t(),s(f,null,{default:o(()=>[p(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E5%88%86%E6%95%B0%20z%22%5D%20--%3E%20MAX%5B%22%E5%87%8F%E5%8E%BB%E8%BD%B4%E4%B8%8A%E6%9C%80%E5%A4%A7%E5%80%BC%22%5D%0A%20%20MAX%20--%3E%20EXP%5B%22%E9%80%90%E5%85%83%E7%B4%A0%E6%8C%87%E6%95%B0%22%5D%0A%20%20EXP%20--%3E%20NORM%5B%22%E9%99%A4%E4%BB%A5%E6%80%BB%E5%92%8C%22%5D%0A%20%20NORM%20--%3E%20P%5B%22%E5%8D%95%E7%BA%AF%E5%BD%A2%E4%B8%8A%E7%9A%84%20p%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>指数放大差距：比最大值小几单位的分量，概率已经可以忽略。这正是「确信」的来源，也是数值与优化的来源。分数尺度若被上一课的未归一点积抬到几十，softmax 几乎变成 one-hot，梯度消失在错误的那一侧。减最大值只救溢出，不救饱和：饱和是几何问题，要靠后课的缩放、归一化或学习率来管。</p><p>平移不变意味着绝对分数没有意义，只有相对差距有意义。因此把 \\(z\\) 加上与类别无关的常数，不改预测。层归一化、偏置、残差里那些「整体抬升」的自由度，有一部分会被 softmax 吃掉；这不是 bug，是接口的商空间。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写交叉熵，也不写 \\(\\mathrm{softmax}(QK^\\top/\\sqrt{d})\\)。下一课<a href="/llm/cross-entropy-mle">交叉熵与极大似然</a>才把 \\(p\\) 与标签接上。对数空间的 \\(\\mathrm{logsumexp}\\) 是再下一课。后课默认：需要概率时，在指定轴上做稳定 softmax；掩码在指数之前写入。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Softmax 把实数分数映到单纯形；对平移不变，对正缩放会变尖。</li><li>先减轴上最大值再指数，避免溢出；这不改变 \\(p\\)。</li><li>掩码必须写进分数，不能在归一之后再乘零。</li><li>饱和时 Jacobian 接近零，分数尺度过大会让训练停住。</li><li>出处：Bridle, 1990；Goodfellow et al., Deep Learning, 2016。</li></ul>',7))])}const A=i(d,[["render",h]]);export{b as __pageData,A as default};
